window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[92]={"id":"092","numero":92,"titre":"Déficit sensitif et/ou moteur des membres","objectifs":[{"id":"92-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique syndromique et topographique devant un déficit moteur et/ou sensitif des membres","contenu":"<h4>1. Éliminer d'abord les causes non neurologiques</h4>\n      <table >\n        <thead>\n          <tr><th>Origine</th><th>Présentation évocatrice</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Ostéo-articulaire</span></td>\n            <td><span class=\"kw-clinique\">Fracture</span> ; <span class=\"kw-clinique\">arthrite aiguë</span> ; <span class=\"kw-clinique\">tendinite</span> → <span class=\"kw-clinique\">impotence fonctionnelle</span> (pas de vrai déficit moteur)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Vasculaire</span></td>\n            <td><span class=\"kw-etio\">AOMI</span> : <span class=\"kw-clinique\">claudication intermittente douloureuse</span> (crampes d'un ou deux mollets) avec <span class=\"kw-clinique\">réduction du périmètre de marche</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Psychogène</span></td>\n            <td>\n              <span class=\"kw-clinique\">Contexte de choc émotionnel</span><br>\n              <span class=\"kw-clinique\">Discordance anatomo-clinique</span> : le déficit ne correspond à aucune systématisation neurologique<br>\n              <span class=\"kw-clinique\">Discordance</span> entre le testing musculaire et les mouvements des actes courants<br>\n              <span class=\"kw-clinique\">Manque de reproductibilité</span> des signes d'un examen à l'autre\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. Syndromes moteurs — tableau syndromique</h4>\n      <table >\n        <thead>\n          <tr>\n            <th></th>\n            <th><span class=\"kw-def\">Syndrome pyramidal</span></th>\n            <th><span class=\"kw-def\">Syndrome neurogène périphérique</span></th>\n            <th><span class=\"kw-def\">Syndrome myasthénique</span></th>\n            <th><span class=\"kw-def\">Syndrome myogène</span></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Déficit moteur</strong></td>\n            <td><span class=\"kw-clinique\">Muscles extenseurs aux MS</span> et <span class=\"kw-clinique\">fléchisseurs aux MI</span></td>\n            <td><span class=\"kw-clinique\">Tronculaire, radiculaire</span> ou <span class=\"kw-clinique\">distal bilatéral et symétrique</span></td>\n            <td><span class=\"kw-clinique\">Proximal</span>, <span class=\"kw-clinique\">muscles oculomoteurs</span>, <span class=\"kw-clinique\">pharyngo-laryngés</span></td>\n            <td><span class=\"kw-clinique\">Proximal et symétrique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Amyotrophie</strong></td>\n            <td>Non ou minime</td>\n            <td>Oui</td>\n            <td>Non</td>\n            <td>Oui ou hypertrophie</td>\n          </tr>\n          <tr>\n            <td><strong>ROT</strong></td>\n            <td><span class=\"kw-clinique\">Vifs et diffus</span> (sauf si brutal : <span class=\"kw-clinique\">paralysie flasque</span>)</td>\n            <td><span class=\"kw-clinique\">Faibles ou abolis</span></td>\n            <td>Normaux</td>\n            <td>Normaux</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">RCP</span></strong></td>\n            <td><span class=\"kw-clinique\">Signe de Babinski</span></td>\n            <td>En flexion</td>\n            <td>En flexion</td>\n            <td>En flexion</td>\n          </tr>\n          <tr>\n            <td><strong>Tonus</strong></td>\n            <td><span class=\"kw-clinique\">Spasticité</span> (<span class=\"kw-clinique\">flasque</span> si brutal)</td>\n            <td><span class=\"kw-clinique\">Hypotonie</span> ou normal</td>\n            <td>Normal</td>\n            <td><span class=\"kw-clinique\">Hypotonie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Fasciculations</strong></td>\n            <td>Non</td>\n            <td>Possibles</td>\n            <td>Non</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Réflexe idiomusculaire</strong></td>\n            <td>Présent</td>\n            <td>Présent</td>\n            <td>Présent</td>\n            <td><span class=\"kw-clinique\">Aboli</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3. Étages anatomiques de la voie motrice</h4>\n      <table >\n        <thead>\n          <tr><th>Étage anatomique</th><th>Syndrome au membre</th><th>Syndrome au visage</th><th>Syndrome pharyngo-laryngé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">1er motoneurone</span></td>\n            <td><span class=\"kw-def\">Syndrome pyramidal</span></td>\n            <td><span class=\"kw-clinique\">Paralysie faciale centrale</span></td>\n            <td><span class=\"kw-def\">Syndrome pseudo-bulbaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">2e motoneurone</span></td>\n            <td><span class=\"kw-def\">Syndrome neurogène périphérique</span></td>\n            <td><span class=\"kw-clinique\">Paralysie faciale périphérique</span></td>\n            <td><span class=\"kw-def\">Syndrome bulbaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Plaque motrice</span></td>\n            <td colspan=\"3\"><span class=\"kw-def\">Syndrome myasthénique</span> — altération de la transmission neuromusculaire ; pré-synaptique : <span class=\"kw-etio\">syndrome de Lambert-Eaton</span> (défaut de libération d'acétylcholine) ; post-synaptique : <span class=\"kw-etio\">myasthénie</span> (diminution des récepteurs à l'acétylcholine fonctionnels)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Muscle</span></td>\n            <td colspan=\"3\"><span class=\"kw-def\">Syndrome myogène</span> (myopathique) — altération des fibres musculaires</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>4. Démarche topographique</h4>\n      <table >\n        <thead>\n          <tr><th>Présentation</th><th>Siège lésionnel possible</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Tétraplégie</td>\n            <td><span class=\"kw-def\">Tronc cérébral</span> ou <span class=\"kw-etio\">moelle cervicale haute</span></td>\n          </tr>\n          <tr>\n            <td>Paraplégie</td>\n            <td>\n              <strong>Médullaire :</strong> <span class=\"kw-etio\">moelle cervicale basse</span>, <span class=\"kw-etio\">thoracique</span> ou <span class=\"kw-etio\">cône terminal</span><br>\n              <strong>Pluriradiculaire :</strong> <span class=\"kw-etio\">syndrome de la queue de cheval</span> ; <span class=\"kw-etio\">polyradiculoneuropathie</span><br>\n              <strong>Bifrontal :</strong> <span class=\"kw-etio\">méningiome de la faux du cerveau</span> ; <span class=\"kw-etio\">infarctus cérébral antérieur bilatéral</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Hémiplégie</td>\n            <td>\n              <strong>Cortical :</strong> <span class=\"kw-clinique\">hémiplégie non proportionnelle</span> + signes corticaux associés (aphasie, héminégligence)<br>\n              <strong>Capsule interne :</strong> <span class=\"kw-clinique\">hémiplégie proportionnelle</span><br>\n              <strong>Tronc cérébral :</strong> <span class=\"kw-def\">syndrome alterne</span> (nerf crânien ipsilatéral + déficit moteur controlatéral)<br>\n              <strong>Moelle cervicale haute :</strong> <span class=\"kw-def\">syndrome de Brown-Séquard</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>5. Orientation étiologique de l'hémiplégie selon le mode d'installation</h4>\n      <table >\n        <thead>\n          <tr><th>Mode d'installation</th><th>Étiologies à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Brutale prolongée</span> (secondes à heures, sans trauma)</td>\n            <td><span class=\"kw-etio\">AVC ischémique</span> (<span class=\"kw-clinique\">infarctus</span> cérébral) ++ ; <span class=\"kw-etio\">AVC hémorragique</span> (hématome intracérébral) ; rarement <span class=\"kw-etio\">tumeur cérébrale</span> (par hémorragie intratumorale)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Progressive</span></td>\n            <td>Processus expansif intracrânien : <span class=\"kw-etio\">tumeur cérébrale</span> ; <span class=\"kw-etio\">abcès cérébral</span> (pyogène, <span class=\"kw-etio\">toxoplasmose</span>, <span class=\"kw-etio\">tuberculome</span>) ; <span class=\"kw-etio\">hématome sous-dural chronique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Brutale transitoire</span></td>\n            <td>Principal : <span class=\"kw-etio\">AIT</span>. DD : <span class=\"kw-etio\">crise d'épilepsie partielle motrice</span> avec déficit post-critique (<span class=\"kw-def\">paralysie de Todd</span>) ; <span class=\"kw-etio\">hypoglycémie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">À bascule</span> (un côté puis l'autre)</td>\n            <td>Accidents ischémiques du territoire <span class=\"kw-etio\">vertébro-basilaire</span> (<span class=\"kw-clinique\">claudication</span> du tronc basilaire) ; <span class=\"kw-etio\">thrombophlébite du sinus longitudinal supérieur</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Post-traumatique</span> (heures à jours)</td>\n            <td><span class=\"kw-etio\">Hématome extra-dural</span> ; <span class=\"kw-etio\">hématome sous-dural aigu</span> ; <span class=\"kw-etio\">hématome intracérébral</span> ; <span class=\"kw-etio\">contusion cérébrale</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Contexte fébrile</span></td>\n            <td><span class=\"kw-etio\">Abcès cérébral</span> ; <span class=\"kw-etio\">endocardite bactérienne</span> avec complication neurologique ; <span class=\"kw-etio\">méningo-encéphalite</span> (<span class=\"kw-etio\">bactérienne</span> / parasitaire / virale) ; <span class=\"kw-etio\">thrombophlébite cérébrale septique</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-def\">motoneurone central</span> et <span class=\"kw-def\">périphérique</span> peuvent coexister (ex : <span class=\"kw-etio\">SLA</span>, <span class=\"kw-etio\">myélopathie cervicale haute</span>) — toujours examiner <span class=\"kw-clinique\">ROT</span>, <span class=\"kw-clinique\">RCP</span> et <span class=\"kw-clinique\">fasciculations</span> pour ne pas trancher trop vite.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 98 — Myasthénie · 96 — Neuropathie périphérique</em></p>","frequence":5},{"id":"92-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","contenu":"<table >\n        <thead>\n          <tr><th>Type de complications</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Complications générales</strong></td>\n            <td>\n              <strong>Thrombo-emboliques :</strong> <span class=\"kw-alerte\">risque si confiné au lit</span> — prévention par <span class=\"kw-ttt\">anticoagulation à dose isocoagulante</span>, <span class=\"kw-clinique\">mobilisation</span> et stimulation mécanique du retour veineux<br>\n              <strong>Bronchopulmonaires :</strong> <span class=\"kw-clinique\">encombrement bronchique</span> et <span class=\"kw-alerte\">fausses routes</span> favorisés par l'alitement<br>\n              <strong>Traumatiques :</strong> <span class=\"kw-alerte\">chutes lors de la reprise de la marche</span> (par déficit moteur ou trouble proprioceptif sévère)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Complications loco-régionales</strong></td>\n            <td>\n              <strong>Escarres :</strong> <span class=\"kw-alerte\">talons et sacrum</span> — mesures de prévention dédiées<br>\n              <strong>Enraidissement :</strong> risque de <span class=\"kw-clinique\">rétraction</span> (sur hypertonie pyramidale notamment) ; <span class=\"kw-clinique\">périarthrite scapulo-humérale</span> ; <span class=\"kw-clinique\">ostéome para-articulaire</span> (coude, genou) ; <span class=\"kw-clinique\">spasticité</span> — prise en charge : kinésithérapie + <span class=\"kw-ttt\">toxine botulique</span><br>\n              <strong>Algoneurodystrophie du membre supérieur :</strong> prévention par <span class=\"kw-ttt\">kinésithérapie douce indolore</span> ; traitement : repos + refroidissement du membre<br>\n              <strong>Traumatisme sensitif :</strong> <span class=\"kw-alerte\">brûlures non perçues</span> à la main ; <span class=\"kw-alerte\">mal perforant plantaire</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-clinique\">rééducation fonctionnelle</span> est toujours requise devant tout déficit sensitivo-moteur.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 119 — Soins et accompagnement dans la maladie chronique et le handicap · 340 — <span class=\"kw-alerte\">AVC</span></em></p>","frequence":0},{"id":"92-3","rang":"A","rubrique":"Examens complémentaires","titre":"Hiérarchiser les examens complémentaires devant un déficit moteur et/ou sensitif d’un membre","contenu":"<table >\n        <thead>\n          <tr><th>Présentation clinique</th><th>Examen(s) complémentaire(s)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td colspan=\"2\"><strong>Déficit moteur aigu d'origine <span class=\"kw-def\">centrale</span></strong></td>\n          </tr>\n          <tr>\n            <td>Hémiplégie</td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span></td>\n          </tr>\n          <tr>\n            <td>Syndrome alterne</td>\n            <td><span class=\"kw-imagerie\">IRM</span> centrée sur le tronc cérébral</td>\n          </tr>\n          <tr>\n            <td>Paraplégie / Tétraplégie</td>\n            <td><span class=\"kw-imagerie\">IRM médullaire</span></td>\n          </tr>\n          <tr>\n            <td colspan=\"2\"><strong>Déficit moteur aigu d'origine <span class=\"kw-def\">périphérique</span></strong></td>\n          </tr>\n          <tr>\n            <td>Queue de cheval</td>\n            <td><span class=\"kw-imagerie\">IRM médullaire</span></td>\n          </tr>\n          <tr>\n            <td>Tétraparésie progressive</td>\n            <td><span class=\"kw-imagerie\">ENMG</span> + <span class=\"kw-bio\">ponction lombaire</span></td>\n          </tr>\n          <tr>\n            <td>Mononévrite multiple</td>\n            <td><span class=\"kw-imagerie\">ENMG</span> ± <span class=\"kw-bio\">biopsie neuromusculaire</span></td>\n          </tr>\n          <tr>\n            <td>Fatigabilité / Fluctuation</td>\n            <td><span class=\"kw-imagerie\">ENMG</span> (stimulation répétitive)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Objectif</th><th>Examens</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Diagnostic topographique</strong></td>\n            <td>\n              <strong>SNC :</strong> <span class=\"kw-imagerie\">IRM/TDM cérébrale</span>, <span class=\"kw-imagerie\">IRM médullaire</span><br>\n              <strong>SNP / JNM / muscle :</strong> <span class=\"kw-imagerie\">ENMG</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Ponction</span> lombaire</strong></td>\n            <td><span class=\"kw-bio\">PL</span> si : atteinte proximale (<span class=\"kw-etio\">polyradiculonévrite aiguë</span>, <span class=\"kw-etio\">méningoradiculite</span>) ; suspicion <span class=\"kw-etio\">inflammatoire</span>/infectieuse du SNC (<span class=\"kw-etio\">SEP</span>, <span class=\"kw-etio\">paranéoplasique</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>Au cas par cas : <span class=\"kw-bio\">SIB</span> ; <span class=\"kw-bio\">glycémie</span> (<span class=\"kw-etio\">diabète</span>) ; <span class=\"kw-bio\">électrophorèse des protéines</span> (<span class=\"kw-etio\">gammapathie monoclonale</span>) ; <span class=\"kw-bio\">vitamines B12/B9</span> ; <span class=\"kw-bio\">TSH</span> (<span class=\"kw-etio\">hypothyroïdie</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Biopsie</span></strong></td>\n            <td><span class=\"kw-bio\">Biopsie musculaire</span> ou <span class=\"kw-bio\">biopsie neuromusculaire</span> — confirmation histologique d'un syndrome neurogène périphérique ou myogène + arguments étiologiques</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan systématique en <span class=\"kw-alerte\">urgence</span> devant une hémiplégie brutale</h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Examens à réaliser</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td><span class=\"kw-imagerie\">IRM cérébrale</span> ou, à défaut, <span class=\"kw-imagerie\">scanner cérébral</span></td>\n          </tr>\n          <tr>\n            <td><strong>Bilan <span class=\"kw-ttt\">biologique</span> standard</strong></td>\n            <td><span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">plaquettes</span> ; <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">TP</span> ; <span class=\"kw-bio\">TCA</span> ; <span class=\"kw-bio\">ionogramme sanguin</span> ; <span class=\"kw-bio\">urée</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">glycémie</span> ; <span class=\"kw-bio\">enzymes cardiaques</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cardiologie</strong></td>\n            <td><span class=\"kw-imagerie\">ECG</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute <span class=\"kw-alerte\">hémiplégie brutale</span> = <span class=\"kw-imagerie\">IRM cérébrale</span> dans les <span class=\"kw-chiffre\">4 h 30</span> (fenêtre <span class=\"kw-ttt\">thrombolyse</span>) ; à défaut, <span class=\"kw-imagerie\">scanner cérébral</span> sans injection pour éliminer une hémorragie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-alerte\">AVC</span> · 96 — Neuropathie périphérique · 98 — Myasthénie</em></p>","frequence":3},{"id":"92-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la valeur localisatrice d’un syndrome sensitif alterne et citer un exemple","contenu":"<p><span class=\"kw-def\">Syndrome sensitif alterne</span> = association d'une atteinte sensitive <strong>hémicorporelle controlatérale</strong> à la <span class=\"kw-clinique\">lésion</span> + atteinte d'un <strong>nerf crânien homolatéral</strong> à la lésion → signe l'atteinte du <span class=\"kw-def\">tronc cérébral</span>.</p>\n      <p><strong>Mécanisme :</strong> les voies <span class=\"kw-def\">lemniscales</span> (tact épicritique + proprioception) croisent à la <span class=\"kw-def\">décussation bulbaire</span>, tandis que les voies <span class=\"kw-def\">extralemniscales</span> (spinothalamiques, thermoalgiques) croisent dès la moelle. Dans le tronc, les deux systèmes cheminent séparément, permettant une <span class=\"kw-clinique\">dissociation sensitive</span>.</p>\n\n      <h4>Exemple type — <span class=\"kw-clinique\">Syndrome de Wallenberg</span></h4>\n      <p><span class=\"kw-def\">Infarctus latéro-bulbaire</span> dans le territoire de la <span class=\"kw-etio\">PICA</span> (artère cérébelleuse postéro-inférieure).</p>\n      <table >\n        <thead>\n          <tr><th>Signe</th><th>Topographie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Anesthésie thermoalgique de l'hémiface</span></td>\n            <td>Ipsilatérale — atteinte du noyau spinal du <span class=\"kw-def\">V (trijumeau)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Anesthésie thermoalgique de l'hémicorps</span></td>\n            <td>Controlatérale — atteinte du <span class=\"kw-def\">faisceau spinothalamique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Syndrome cérébelleux</span></td>\n            <td>Ipsilatéral — atteinte des fibres cérébelleuses</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Syndrome vestibulaire</span></td>\n            <td>Ipsilatéral — atteinte des noyaux vestibulaires</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Claude-Bernard-Horner (CBH)</span></td>\n            <td>Ipsilatéral — atteinte des fibres sympathiques descendantes</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Atteinte IX-X</span> (dysphonie, dysphagie)</td>\n            <td>Ipsilatérale — atteinte des noyaux ambigus</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Discriminant clé.</strong> Devant un déficit sensitif <span class=\"kw-clinique\">dissocié</span> (épicritique préservée, thermoalgique abolie, ou inversement), penser <span class=\"kw-def\">tronc cérébral</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-alerte\">AVC</span> · 91 — Déficit neuro récent</em></p>","frequence":4},{"id":"92-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","contenu":"<table >\n        <thead>\n          <tr><th>Niveau anatomique</th><th>Signes associés discriminants</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cortical</span></td>\n            <td><span class=\"kw-clinique\">Hémiplégie non proportionnelle</span> ; <span class=\"kw-clinique\">aphasie</span> ; <span class=\"kw-clinique\">héminégligence</span> ; <span class=\"kw-clinique\">hémianopsie</span> ; troubles sensitifs corticaux (<span class=\"kw-clinique\">astéréognosie</span>, <span class=\"kw-clinique\">extinction</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Capsule interne</span></td>\n            <td><span class=\"kw-clinique\">Hémiplégie proportionnelle</span> — pas de signes corticaux associés</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Thalamus</span></td>\n            <td><span class=\"kw-clinique\">Hypoesthésie controlatérale proportionnelle des 3 étages</span> et <span class=\"kw-clinique\">à tous les modes</span> (tact, proprioception, thermoalgique) — <span class=\"kw-clinique\">pas de déficit moteur</span> (piège EDN : déficit sensitif pur = thalamus)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Tronc cérébral</span></td>\n            <td><span class=\"kw-def\">Syndrome alterne</span> : atteinte d'un <span class=\"kw-clinique\">nerf crânien homolatéral</span> + déficit moteur et/ou sensitif <span class=\"kw-clinique\">controlatéral</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Moelle cervicale haute</span></td>\n            <td><span class=\"kw-def\">Syndrome de Brown-Séquard</span> : <span class=\"kw-clinique\">hémiparésie</span> + <span class=\"kw-clinique\">abolition du tact épicritique et de la proprioception homolatéraux</span> + <span class=\"kw-clinique\">anesthésie thermoalgique controlatérale</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Moelle thoracique / lombaire</span></td>\n            <td><span class=\"kw-clinique\">Niveau sensitif</span> ; <span class=\"kw-clinique\">syndrome pyramidal sous-lésionnel</span> ; troubles génito-sphinctériens</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Racine</span></td>\n            <td><span class=\"kw-clinique\">Douleur radiculaire</span> au premier plan ± déficit moteur si atteinte de la racine antérieure</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Nerf périphérique</span></td>\n            <td><span class=\"kw-clinique\">Déficit tronculaire</span> unique ou multiple ; ou <span class=\"kw-clinique\">polyneuropathie distale et symétrique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Jonction neuromusculaire (JNM)</span></td>\n            <td><span class=\"kw-clinique\">Fatigabilité</span> à l'effort ; <span class=\"kw-clinique\">fluctuation</span> dans la journée ; <span class=\"kw-clinique\">atteinte oculomotrice</span> (<span class=\"kw-clinique\">ptosis</span>, <span class=\"kw-clinique\">diplopie</span>) ; <span class=\"kw-clinique\">atteinte pharyngo-laryngée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Muscle</span></td>\n            <td><span class=\"kw-clinique\">Déficit proximal et symétrique</span> ; <span class=\"kw-clinique\">abolition du réflexe idiomusculaire</span> ; pas de trouble sensitif</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège du sujet âgé.</strong> Plusieurs étages peuvent coexister (<span class=\"kw-etio\">canal lombaire étroit</span> + <span class=\"kw-etio\">neuropathie diabétique</span> + <span class=\"kw-etio\">AVC ancien</span>). Voir obj-6.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 98 — Myasthénie · 96 — Neuropathie périphérique</em></p>","frequence":0},{"id":"92-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux syndromes médullaires responsables de déficit moteur et sensitif","contenu":"<table >\n        <thead>\n          <tr><th>Syndrome médullaire</th><th>Description clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Lésion médullaire complète</span> (section transverse)</td>\n            <td>\n              <strong>Moteur :</strong> <span class=\"kw-clinique\">tétra-/paraplégie flasque</span> puis <span class=\"kw-clinique\">spastique</span> sous-lésionnelle<br>\n              <strong>Sensitif :</strong> <span class=\"kw-clinique\">anesthésie complète</span> à tous les modes sous-lésionnelle<br>\n              <strong>Sphinctérien :</strong> <span class=\"kw-clinique\">rétention urinaire</span> ; <span class=\"kw-clinique\">rétention fécale</span> ; <span class=\"kw-clinique\">troubles sexuels</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Hémisection médullaire</span> — <span class=\"kw-clinique\">syndrome de Brown</span>-Séquard</td>\n            <td>\n              <strong>Homolatéral :</strong> <span class=\"kw-clinique\">hémiplégie</span> + <span class=\"kw-clinique\">abolition du tact épicritique</span> + <span class=\"kw-clinique\">abolition de la proprioception</span> (voie lemniscale — croise à la <span class=\"kw-def\">décussation bulbaire</span>)<br>\n              <strong>Controlatéral :</strong> <span class=\"kw-clinique\">anesthésie thermoalgique</span> sous-lésionnelle (voie spinothalamique — croise dès la moelle)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Atteinte centro-médullaire</span> (syringomyélie, contusion)</td>\n            <td>\n              <span class=\"kw-clinique\">Hypoesthésie thermoalgique suspendue</span> (en « pèlerine » cervicale) — atteinte des fibres croisant la commissure antérieure<br>\n              <strong>Préserve</strong> les sensibilités lemniscales (proprioception, tact épicritique conservés)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 412\" role=\"img\" aria-label=\"Coupe transversale de la moelle épinière illustrant le syndrome de Brown-Séquard par hémisection médullaire gauche. Du côté de la lésion, à gauche, sont interrompues la voie lemniscale du cordon postérieur, qui porte le tact épicritique et la proprioception et ne croise qu'à la décussation bulbaire plus haut, ainsi que le faisceau pyramidal cortico-spinal latéral, déjà croisé ; il en résulte du côté homolatéral à la lésion une hémiplégie et une abolition du tact épicritique et de la proprioception. Le faisceau spinothalamique, qui porte la sensibilité thermoalgique, croise au contraire dès la moelle par la commissure antérieure, si bien que l'anesthésie thermoalgique est observée du côté controlatéral, à droite, sous le niveau de la lésion. En bas, deux silhouettes corporelles résument cette dissociation : à gauche, du côté de la lésion, déficit moteur et perte du tact et de la proprioception ; à droite, perte de la sensibilité thermoalgique.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"22\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"700\">Hémisection médullaire — <span class=\"kw-clinique\">syndrome de Brown</span>-Séquard</text>\n          <text class=\"tx-muted\" x=\"280\" y=\"40\" text-anchor=\"middle\" font-size=\"10\">Coupe transversale : dissociation lemniscale (homolatérale) / spinothalamique (controlatérale)</text>\n\n          <text class=\"tx-red\" x=\"118\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">CÔTÉ LÉSÉ (gauche)</text>\n          <text class=\"tx-grey\" x=\"320\" y=\"60\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">Côté sain (droit)</text>\n\n          <ellipse class=\"fb-grey\" cx=\"218\" cy=\"150\" rx=\"120\" ry=\"86\"/>\n          <line class=\"ln\" x1=\"218\" y1=\"66\" x2=\"218\" y2=\"236\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n          <polygon class=\"fb-grey\" points=\"218,108 168,128 168,172 218,192 268,172 268,128\"/>\n          <rect class=\"fb-red\" x=\"98\" y=\"72\" width=\"120\" height=\"156\" rx=\"4\" opacity=\"0.55\"/>\n          <text class=\"tx-red\" x=\"158\" y=\"92\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Hémisection</text>\n\n          <circle class=\"fb-purple\" cx=\"200\" cy=\"120\" r=\"13\"/>\n          <text class=\"tx-purple\" x=\"200\" y=\"124\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">L</text>\n          <text class=\"tx-purple\" x=\"148\" y=\"120\" text-anchor=\"middle\" font-size=\"9.5\">Cordon post.</text>\n          <text class=\"tx-purple\" x=\"148\" y=\"132\" text-anchor=\"middle\" font-size=\"9.5\">(lemniscal)</text>\n\n          <circle class=\"fb-amber\" cx=\"186\" cy=\"168\" r=\"13\"/>\n          <text class=\"tx-amber\" x=\"186\" y=\"172\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">P</text>\n          <text class=\"tx-amber\" x=\"138\" y=\"170\" text-anchor=\"middle\" font-size=\"9.5\">Pyramidal</text>\n\n          <circle class=\"fb-teal\" cx=\"252\" cy=\"178\" r=\"13\"/>\n          <text class=\"tx-teal\" x=\"252\" y=\"182\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">T</text>\n          <line class=\"ln\" x1=\"208\" y1=\"186\" x2=\"240\" y2=\"180\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"246,179 238,176 239,184\"/>\n          <text class=\"tx-teal\" x=\"318\" y=\"178\" text-anchor=\"middle\" font-size=\"9.5\">Spinothalamique</text>\n          <text class=\"tx-teal\" x=\"318\" y=\"190\" text-anchor=\"middle\" font-size=\"9.5\">croise dès la moelle</text>\n\n          <line class=\"ln\" x1=\"128\" y1=\"240\" x2=\"128\" y2=\"262\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"128,268 123,260 133,260\"/>\n          <line class=\"ln\" x1=\"392\" y1=\"240\" x2=\"392\" y2=\"262\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"392,268 387,260 397,260\"/>\n\n          <rect class=\"fb-amber\" x=\"22\" y=\"270\" width=\"256\" height=\"124\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"150\" y=\"290\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Homolatéral (côté lésé)</text>\n          <text class=\"tx-amber\" x=\"40\" y=\"314\" font-size=\"11\">• Hémiplégie (faisceau pyramidal)</text>\n          <text class=\"tx-amber\" x=\"40\" y=\"336\" font-size=\"11\">• Abolition du tact épicritique</text>\n          <text class=\"tx-amber\" x=\"40\" y=\"356\" font-size=\"11\">• Abolition de la proprioception</text>\n          <text class=\"tx-muted\" x=\"40\" y=\"370\" font-size=\"10\">(voie lemniscale : croise</text>\n          <text class=\"tx-muted\" x=\"40\" y=\"382\" font-size=\"10\">en haut, au bulbe)</text>\n\n          <rect class=\"fb-teal\" x=\"290\" y=\"270\" width=\"248\" height=\"124\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"414\" y=\"290\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\">Controlatéral (côté sain)</text>\n          <text class=\"tx-teal\" x=\"308\" y=\"318\" font-size=\"11\">• Anesthésie thermoalgique</text>\n          <text class=\"tx-teal\" x=\"308\" y=\"340\" font-size=\"11\">  sous-lésionnelle</text>\n          <text class=\"tx-muted\" x=\"308\" y=\"368\" font-size=\"10\">(voie spinothalamique : croise</text>\n          <text class=\"tx-muted\" x=\"308\" y=\"382\" font-size=\"10\">dès la moelle → côté opposé)</text>\n        </svg>\n        <figcaption>Brown-Séquard : la <span class=\"kw-clinique\">lésion</span> d'un hémicordon donne un déficit moteur + lemniscal du côté lésé (homolatéral) et un déficit thermoalgique du côté opposé (controlatéral), car le faisceau spinothalamique a déjà croisé dans la moelle.</figcaption>\n      </figure>\n\n      <p><strong>Latéralité des déficits sensitifs :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Voie lemniscale</span> (tact épicritique, proprioception) : croise à la <span class=\"kw-def\">décussation bulbaire</span> → déficit sensitif <span class=\"kw-clinique\">homolatéral</span> si <span class=\"kw-clinique\">lésion</span> médullaire en dessous</li>\n        <li><span class=\"kw-def\">Voie spinothalamique</span> (thermoalgique) : croise dès la moelle → déficit thermoalgique <span class=\"kw-clinique\">controlatéral</span> si atteinte du cordon latéral ou plus haut</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute <span class=\"kw-alerte\">compression médullaire</span> avec <span class=\"kw-clinique\">déficit moteur</span> + <span class=\"kw-clinique\">niveau sensitif</span> + <span class=\"kw-clinique\">troubles sphinctériens</span> = <span class=\"kw-imagerie\">IRM médullaire</span> en urgence (dans les <span class=\"kw-chiffre\">6 h</span>) + avis neurochirurgical.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 91 — Déficit neuro récent · 104 — SEP</em></p>","frequence":1},{"id":"92-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’origine souvent multifactorielle d’un déficit moteur d’un ou plusieurs membres chez le sujet âgé","contenu":"<p>Chez le sujet âgé, un déficit moteur est rarement <span class=\"kw-def\">monofactoriel</span> — il faut <strong>systématiquement</strong> chercher l'empilement de causes.</p>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Causes fréquemment intriquées</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Neurologique central</strong></td>\n            <td><span class=\"kw-etio\">AVC ancien ou en cours</span> ; <span class=\"kw-etio\">démence vasculaire</span> ; <span class=\"kw-etio\">hématome sous-dural chronique</span> ; <span class=\"kw-etio\">maladie de Parkinson</span></td>\n          </tr>\n          <tr>\n            <td><strong>Neurologique périphérique</strong></td>\n            <td><span class=\"kw-etio\">neuropathie diabétique</span> ; <span class=\"kw-etio\">canal lombaire étroit</span> ; <span class=\"kw-etio\">polyneuropathie carentielle</span> (<span class=\"kw-bio\">vitamine B12</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Musculo-squelettique</strong></td>\n            <td><span class=\"kw-etio\">sarcopénie</span> ; <span class=\"kw-etio\">arthrose invalidante</span> ; <span class=\"kw-etio\">fracture ostéoporotique</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Iatrogène</span></strong></td>\n            <td><span class=\"kw-ttt\">benzodiazépines</span> ; <span class=\"kw-ttt\">neuroleptiques</span> ; <span class=\"kw-ttt\">statines</span> (myopathie) ; <span class=\"kw-ttt\">hypotenseurs</span> (<span class=\"kw-clinique\">hypotension</span> orthostatique)</td>\n          </tr>\n          <tr>\n            <td><strong>Métabolique</strong></td>\n            <td><span class=\"kw-etio\">hypothyroïdie</span> ; <span class=\"kw-etio\">hypoglycémie</span> ; <span class=\"kw-etio\">dyskaliémie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Fonctionnel</strong></td>\n            <td><span class=\"kw-etio\">confinement au lit</span> ; <span class=\"kw-etio\">peur de tomber post-chute</span> ; <span class=\"kw-etio\">dénutrition</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant un sujet âgé qui ne marche plus, <span class=\"kw-ci\">ne jamais</span> s'arrêter à une seule cause. Bilan systématique : <span class=\"kw-clinique\">neurologique</span> + <span class=\"kw-clinique\">locomoteur</span> + <span class=\"kw-clinique\">iatrogène</span> + <span class=\"kw-clinique\">métabolique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 131 — Troubles de la marche et de l'équilibre du sujet âgé · 132 — Troubles cognitifs du sujet âgé · 247 — <span class=\"kw-etio\">Diabète</span></em></p>","frequence":0}],"astuces":[{"type":"info","titre":"Astuces & pièges","contenu":"<ul>\n<li><strong>Toujours coter le déficit moteur sur l'échelle MRC 0–5</strong> — c'est un réflexe attendu en QCM.</li>\n<li><strong>Syndrome alterne = tronc cérébral</strong>, retiens Wallenberg comme exemple.</li>\n<li><strong>ENMG inutile avant <span class=\"kw-chiffre\">J21</span></strong> pour la dénervation : ne pas le demander en aigu.</li>\n<li><strong>Anesthésie en selle + troubles sphinctériens = queue de cheval = <span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-alerte\">urgence</span></strong>.</li>\n<li><strong>Toute paraparésie alitée = <span class=\"kw-ttt\">HBPM</span> préventive + bas de contention + kiné précoce</strong>, systématiquement.</li>\n</ul>"}],"strategie":{"urgence":"<p><strong>Hémiplégie brutale <span class=\"q\">= <span class=\"kw-alerte\">AVC</span> jusqu'à preuve du contraire</span></strong></p><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span> en <span class=\"kw-alerte\">urgence</span> dans la fenêtre <span class=\"kw-ttt\">thrombolyse</span> <span class=\"kw-chiffre\">&lt; 4h30</span></li><li>à défaut <span class=\"kw-imagerie\">scanner cérébral</span> sans injection pour éliminer une <span class=\"kw-alerte\">hémorragie</span></li></ul><p><strong>Compression médullaire <span class=\"q\">(<span class=\"kw-clinique\">déficit moteur</span> + <span class=\"kw-clinique\">niveau sensitif</span> + <span class=\"kw-alerte\">troubles sphinctériens</span>)</span></strong></p><p><span class=\"kw-imagerie\">IRM médullaire</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 6 h</span>) + <span class=\"kw-alerte\">avis neurochirurgical</span> immédiat</p><p><strong><span class=\"kw-clinique\">Syndrome de la</span> queue de cheval <span class=\"q\">(<span class=\"kw-alerte\">anesthésie en selle</span> + <span class=\"kw-alerte\">rétention urinaire</span>)</span></strong></p><ul><li><span class=\"kw-alerte\">urgence chirurgicale</span> → <span class=\"kw-imagerie\">IRM médullaire</span></li></ul><p><strong>Bilan systématique de l'hémiplégie brutale</strong></p><ul><li><span class=\"kw-imagerie\">IRM/TDM cérébrale</span></li><li><span class=\"kw-bio\">NFS-plaquettes</span></li><li><span class=\"kw-bio\">CRP</span></li><li><span class=\"kw-bio\">TP-TCA</span></li><li><span class=\"kw-bio\">ionogramme</span></li><li><span class=\"kw-bio\">urée-créatinine</span></li><li><span class=\"kw-bio\">glycémie</span></li><li><span class=\"kw-bio\">enzymes cardiaques</span></li><li><span class=\"kw-imagerie\">ECG</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Hémiplégie brutale</span> (suspicion d'<span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">ischémique</span> ou hémorragique)</li><li><span class=\"kw-alerte\">Déficit moteur + niveau sensitif + troubles sphinctériens</span> (compression médullaire)</li><li><span class=\"kw-alerte\">Anesthésie en selle + rétention urinaire</span> (<span class=\"kw-clinique\">syndrome de la</span> queue de cheval)</li><li>Déficit dans un <span class=\"kw-alerte\">contexte fébrile</span> (<span class=\"kw-etio\">abcès cérébral</span>, <span class=\"kw-etio\">endocardite</span>, <span class=\"kw-etio\">méningo-encéphalite</span>)</li><li>Déficit d'<span class=\"kw-alerte\">installation progressive</span> (processus expansif : <span class=\"kw-etio\">tumeur</span>, <span class=\"kw-etio\">hématome sous-dural chronique</span>)</li><li>Coexistence <span class=\"kw-clinique\">central + périphérique</span> (penser <span class=\"kw-etio\">SLA</span>, <span class=\"kw-etio\">myélopathie cervicale</span>)</li><li><span class=\"kw-alerte\">Détresse respiratoire</span> sur atteinte proximale ascendante (<span class=\"kw-etio\">polyradiculonévrite</span>, <span class=\"kw-etio\">myasthénie</span>)</li></ul>","principes":"<p><strong>Règle d'or :</strong> la <span class=\"kw-clinique\">rééducation fonctionnelle</span> est <strong>toujours</strong> requise devant un déficit sensitivo-moteur ; le <span class=\"kw-ttt\">traitement étiologique</span> dépend de la cause identifiée (cf. arbre + renvois).</p><p><strong>Prévention thrombo-<span class=\"kw-etio\">embolique</span> <span class=\"q\">(si alitement)</span></strong></p><ul><li><span class=\"kw-ttt\">anticoagulation à dose isocoagulante</span> + <span class=\"kw-clinique\">mobilisation</span> et stimulation mécanique du retour veineux</li></ul><p><strong>Prévention des escarres</strong></p><ul><li>points d'appui (<span class=\"kw-clinique\">talons</span>, <span class=\"kw-clinique\">sacrum</span>), changements de position, matelas adapté</li></ul><p><strong>Prévention bronchopulmonaire</strong></p><ul><li>lutte contre l'<span class=\"kw-clinique\">encombrement</span> et les <span class=\"kw-alerte\">fausses routes</span> favorisés par l'alitement</li></ul><p><strong>PEC de la spasticité</strong></p><ul><li><span class=\"kw-ttt\">kinésithérapie</span> avec mobilisation ± <span class=\"kw-ttt\">toxine botulique</span> (prévention rétraction, périarthrite, ostéome para-articulaire)</li></ul><p><strong>Algoneurodystrophie <span class=\"q\">du membre supérieur</span></strong></p><ul><li>prévention par <span class=\"kw-ttt\">kinésithérapie douce indolore</span></li><li>traitement repos + refroidissement</li></ul><p><strong>Protection du membre anesthésié</strong></p><ul><li>prévenir <span class=\"kw-alerte\">brûlures non perçues</span> et <span class=\"kw-alerte\">mal perforant plantaire</span></li></ul><p><strong>Prévention des chutes</strong></p><ul><li>lors de la reprise de la marche (déficit moteur ou trouble proprioceptif sévère)</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/deficit-moteur-etou-sensitif-des-membres","label":"Collège CEN — Déficit moteur et/ou sensitif des membres"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Déficit moteur et/ou sensitif des membres — Premier tri : est-ce neurologique ?","detail":"<h4>Démarche diagnostique — déficit moteur et/ou sensitif des membres — Syndrome → topographie → mode d'installation → examen orienté</h4>","branches":[{"to":"t-non-neuro","label":"Non neurologique (discordance, claudication, impotence)","color":"blue"},{"to":"q-syndrome","label":"Neurologique confirmé","color":"amber"}]},{"id":"t-non-neuro","kind":"terminal","label":"Causes non neurologiques à éliminer","color":"blue","detail":"<h4>Origines à éliminer</h4><ul><li><span class=\"kw-etio\">Ostéo-articulaire</span> : <span class=\"kw-clinique\">fracture</span>, <span class=\"kw-clinique\">arthrite aiguë</span>, <span class=\"kw-clinique\">tendinite</span> → impotence fonctionnelle sans vrai déficit</li><li><span class=\"kw-etio\">Vasculaire (AOMI)</span> : <span class=\"kw-clinique\">claudication intermittente douloureuse</span> + <span class=\"kw-ttt\">réduction</span> du <span class=\"kw-clinique\">périmètre de marche</span></li><li><span class=\"kw-etio\">Psychogène</span> : <span class=\"kw-clinique\">discordance anatomo-clinique</span>, non systématisé, non reproductible, contexte de <span class=\"kw-alerte\">choc</span> émotionnel</li></ul>"},{"id":"q-syndrome","kind":"decision","label":"Quel syndrome moteur ? — ROT, tonus, amyotrophie, fasciculations, réflexe idiomusculaire","branches":[{"to":"q-central","label":"Pyramidal — ROT vifs, Babinski, spasticité","color":"red"},{"to":"q-periph","label":"Neurogène périphérique — ROT abolis, amyotrophie, fasciculations","color":"amber"},{"to":"t-myasthenie","label":"Myasthénique — fatigabilité, fluctuation, oculo/pharyngé","color":"amber"},{"to":"t-myogene","label":"Myogène — proximal symétrique, réflexe idiomusculaire aboli","color":"amber"}]},{"id":"q-central","kind":"decision","label":"Atteinte centrale — quelle topographie ? — Valeur localisatrice des signes associés","branches":[{"to":"q-hemi","label":"Hémiplégie (un hémicorps)","color":"red"},{"to":"t-alterne","label":"Syndrome alterne (NC homolatéral + déficit controlatéral)","color":"amber"},{"to":"t-medullaire","label":"Para/tétraplégie + niveau sensitif + tr. sphinctériens","color":"red"}]},{"id":"q-hemi","kind":"decision","label":"Hémiplégie — mode d'installation ? — Le mode oriente l'étiologie","branches":[{"to":"t-avc","label":"Brutale prolongée (sans trauma)","color":"red"},{"to":"t-ait","label":"Brutale transitoire (régressive < 24 h)","color":"amber"},{"to":"t-expansif","label":"Progressive","color":"amber"},{"to":"t-infectieux","label":"Contexte fébrile","color":"amber"}]},{"id":"t-avc","kind":"terminal","label":"URGENCE AVC → IRM cérébrale","color":"red","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span> en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 4h30</span> (fenêtre <span class=\"kw-ttt\">thrombolyse</span>) ; à défaut <span class=\"kw-imagerie\">scanner</span> sans injection</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">AVC ischémique</span> (<span class=\"kw-clinique\">infarctus</span> cérébral) ++</li><li><span class=\"kw-etio\">AVC hémorragique</span> (hématome intracérébral)</li><li>Rarement <span class=\"kw-etio\">tumeur</span> (hémorragie intratumorale)</li></ul><h4>Renvoi</h4><ul><li>Item 340 — <span class=\"kw-alerte\">AVC</span></li></ul>"},{"id":"t-ait","kind":"terminal","label":"AIT → bilan étiologique urgent","color":"amber","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span> + bilan étiologique vasculaire en <span class=\"kw-alerte\">urgence</span></li></ul><h4>Diagnostics différentiels</h4><ul><li><span class=\"kw-etio\">Crise d'épilepsie partielle motrice</span> avec déficit post-critique (<span class=\"kw-def\">paralysie de Todd</span>)</li><li><span class=\"kw-etio\">Hypoglycémie</span></li></ul><h4>Renvoi</h4><ul><li>Item 340 — <span class=\"kw-alerte\">AVC</span></li></ul>"},{"id":"t-expansif","kind":"terminal","label":"Processus expansif → IRM cérébrale","color":"amber","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span> injectée</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Tumeur cérébrale</span></li><li><span class=\"kw-etio\">Abcès cérébral</span> (pyogène, toxoplasmose, tuberculome)</li><li><span class=\"kw-etio\">Hématome sous-dural chronique</span></li></ul>"},{"id":"t-infectieux","kind":"terminal","label":"Cause infectieuse → IRM + PL","color":"amber","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale</span> + <span class=\"kw-bio\">ponction lombaire</span> ; <span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-imagerie\">ETT</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Abcès cérébral</span></li><li><span class=\"kw-etio\">Endocardite</span> avec complication neurologique</li><li><span class=\"kw-etio\">Méningo-encéphalite</span> (<span class=\"kw-etio\">bactérienne</span> / virale / parasitaire)</li><li><span class=\"kw-etio\">Thrombophlébite cérébrale</span> septique</li></ul>"},{"id":"t-alterne","kind":"terminal","label":"Atteinte du tronc cérébral → IRM tronc","color":"amber","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">IRM</span> centrée sur le tronc cérébral</li></ul><h4>Mécanisme</h4><ul><li><span class=\"kw-def\">Syndrome alterne</span> : <span class=\"kw-clinique\">nerf crânien homolatéral</span> + déficit moteur/sensitif <span class=\"kw-clinique\">controlatéral</span></li></ul><h4>Exemple</h4><ul><li><span class=\"kw-def\">Syndrome de Wallenberg</span> (<span class=\"kw-clinique\">infarctus</span> latéro-bulbaire, territoire <span class=\"kw-etio\">PICA</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 340 — <span class=\"kw-alerte\">AVC</span></li></ul>"},{"id":"t-medullaire","kind":"terminal","label":"URGENCE compression médullaire → IRM médullaire","color":"red","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">IRM médullaire</span> en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 6 h</span> + <span class=\"kw-alerte\">avis neurochirurgical</span></li></ul><h4>Signes</h4><ul><li><span class=\"kw-clinique\">Déficit moteur</span> sous-lésionnel</li><li><span class=\"kw-clinique\">Niveau sensitif</span></li><li><span class=\"kw-alerte\">Troubles génito-sphinctériens</span></li></ul><h4>Topographie</h4><ul><li><span class=\"kw-etio\">Tétraplégie</span> = moelle cervicale haute / tronc · <span class=\"kw-etio\">Paraplégie</span> = moelle thoracique / cône terminal</li></ul><h4>Renvoi</h4><ul><li>Item 91 — Déficit neuro récent · Item 104 — SEP</li></ul>"},{"id":"q-periph","kind":"decision","label":"Atteinte périphérique — quelle topographie ? — Tronculaire, radiculaire, pluriradiculaire","branches":[{"to":"t-queue","label":"Queue de cheval (anesthésie en selle, rétention)","color":"red"},{"to":"t-prn","label":"Tétraparésie progressive / proximale","color":"amber"},{"to":"t-mono","label":"Mononévrite multiple","color":"amber"}]},{"id":"t-queue","kind":"terminal","label":"URGENCE queue de cheval → IRM médullaire","color":"red","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">IRM médullaire</span> en <span class=\"kw-alerte\">urgence</span> + <span class=\"kw-alerte\">avis neurochirurgical</span></li></ul><h4>Signes</h4><ul><li><span class=\"kw-clinique\">Déficit moteur des MI</span></li><li><span class=\"kw-alerte\">Anesthésie en selle</span></li><li><span class=\"kw-alerte\">Rétention urinaire</span> / troubles sphinctériens</li></ul>"},{"id":"t-prn","kind":"terminal","label":"Polyradiculonévrite → ENMG + PL","color":"amber","detail":"<h4>Examens</h4><ul><li><span class=\"kw-imagerie\">ENMG</span> + <span class=\"kw-bio\">ponction lombaire</span> (dissociation albumino-cytologique)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-alerte\">Atteinte respiratoire</span> et déglutition (gravité)</li></ul><h4>Renvoi</h4><ul><li>Item 96 — Neuropathie périphérique</li></ul>"},{"id":"t-mono","kind":"terminal","label":"Mononévrite multiple → ENMG ± biopsie","color":"amber","detail":"<h4>Examens</h4><ul><li><span class=\"kw-imagerie\">ENMG</span> ± <span class=\"kw-bio\">biopsie neuromusculaire</span></li></ul><h4>Orientation</h4><ul><li>Rechercher <span class=\"kw-etio\">vascularite</span>, <span class=\"kw-etio\">diabète</span>, cause systémique</li></ul><h4>Renvoi</h4><ul><li>Item 96 — Neuropathie périphérique</li></ul>"},{"id":"t-myasthenie","kind":"terminal","label":"Atteinte de la jonction → ENMG (stim. répétitive)","color":"amber","detail":"<h4>Examen</h4><ul><li><span class=\"kw-imagerie\">ENMG</span> avec <span class=\"kw-bio\">stimulation répétitive</span> (décrément) ; <span class=\"kw-bio\">anticorps anti-RACh / anti-MuSK</span></li></ul><h4>Mécanisme</h4><ul><li>Post-synaptique : <span class=\"kw-etio\">myasthénie</span> (↓ récepteurs ACh)</li><li>Pré-synaptique : <span class=\"kw-etio\">syndrome de Lambert-Eaton</span> (défaut de libération d'ACh)</li></ul><h4>Renvoi</h4><ul><li>Item 98 — Myasthénie</li></ul>"},{"id":"t-myogene","kind":"terminal","label":"Atteinte musculaire → ENMG + biopsie musculaire","color":"amber","detail":"<h4>Examens</h4><ul><li><span class=\"kw-imagerie\">ENMG</span> (tracé myogène) + <span class=\"kw-bio\">CPK</span> + <span class=\"kw-bio\">biopsie musculaire</span></li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Déficit proximal et symétrique</span></li><li><span class=\"kw-clinique\">Réflexe idiomusculaire aboli</span></li><li>Pas de trouble sensitif</li></ul>"}]},"cards":[{"i":"1e6a37910709","n":92,"o":"92-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit moteur et/ou sensitif des membres","q":"Quelles sont les quatre principales causes non neurologiques à éliminer devant un déficit moteur ou sensitif des membres ?","a":"<p>Les causes non neurologiques à éliminer prioritairement sont :</p><ul><li>Les causes <strong>ostéo-articulaires</strong> (fracture, arthrite aiguë, tendinite), qui se manifestent par une impotence fonctionnelle sans vrai déficit moteur.</li><li>Les causes <strong>vasculaires</strong> (AOMI) avec <strong>claudication intermittente douloureuse</strong>.</li><li>Les causes <strong>psychogènes</strong>, souvent avec discordance anatomo-clinique, discordance entre le testing musculaire et les actes courants, et manque de reproductibilité des signes.</li></ul>"},{"i":"84af35559783","n":92,"o":"92-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit moteur et/ou sensitif des membres","q":"Quelles sont les caractéristiques principales du syndrome myasthénique et du syndrome myogène ?","a":"<p>Les caractéristiques sont :</p><ul><li>Le <strong>syndrome myasthénique</strong> (plaque motrice) se manifeste par un déficit moteur <strong>proximal</strong>, qui affecte les <strong>muscles oculomoteurs</strong> et <strong>pharyngo-laryngés</strong>, sans amyotrophie, des <strong>ROT normaux</strong>, et un tonus normal.</li><li>Le <strong>syndrome myogène</strong> (muscle) se présente comme un déficit moteur <strong>proximal et symétrique</strong>, avec une amyotrophie (parfois hypertrophie), des <strong>ROT normaux</strong>, une <strong>hypotonie</strong>, et sans fasciculations. Le réflexe idiomusculaire est aboli.</li></ul>"},{"i":"bbea603abe6c","n":92,"o":"92-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit moteur et/ou sensitif des membres","q":"Devant une hémiplégie, quelles sont les présentations cliniques suggérant une atteinte corticale, capsulaire interne ou du tronc cérébral ?","a":"<p>Devant une hémiplégie :</p><ul><li>Une atteinte <strong>corticale</strong> se manifeste par une hémiplégie <strong>non proportionnelle</strong>, souvent associée à des <strong>signes corticaux</strong> (aphasie, héminégligence).</li><li>Une atteinte de la <strong>capsule interne</strong> entraîne une hémiplégie <strong>proportionnelle</strong>.</li><li>Une atteinte du <strong>tronc cérébral</strong> est caractérisée par un <strong>syndrome alterne</strong> (atteinte d'un nerf crânien ipsilatéral et déficit moteur controlatéral).</li></ul>"},{"i":"c191dafb5f02","n":92,"o":"92-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit moteur et/ou sensitif des membres","q":"Quel est le piège classique à connaître concernant la coexistence des atteintes du motoneurone central et périphérique ?","a":"<p>Le piège classique est la possibilité de <strong>coexistence d'atteintes du motoneurone central et périphérique</strong>, comme dans la <strong>sclérose latérale amyotrophique (SLA)</strong> ou une <strong>myélopathie cervicale haute</strong>. Il est crucial d'examiner systématiquement les <strong>ROT, les RCP et les fasciculations</strong> pour un diagnostic précis et éviter des conclusions hâtives.</p>"},{"i":"c63a9aff0b15","n":92,"o":"92-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit moteur et/ou sensitif des membres","q":"Quelles sont les principales étiologies à évoquer pour une hémiplégie d'installation brutale prolongée versus brutale transitoire ?","a":"<p>Pour une hémiplégie :</p><ul><li><strong>Brutale prolongée</strong> (secondes à heures, sans traumatisme) : <strong>AVC ischémique (infarctus cérébral)</strong> ++, <strong>AVC hémorragique (hématome intracérébral)</strong>, et plus rarement, une tumeur cérébrale par hémorragie intratumorale.</li><li><strong>Brutale transitoire</strong> : principalement un <strong>AIT</strong> (accident ischémique transitoire). Les diagnostics différentiels incluent une crise d'épilepsie partielle motrice avec déficit post-critique (paralysie de Todd) ou une hypoglycémie.</li></ul>"},{"i":"da06f0ede682","n":92,"o":"92-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique syndromique et topographique devant un déficit moteur et/ou sensitif des membres","q":"Comment différencier un syndrome pyramidal d'un syndrome neurogène périphérique devant un déficit moteur ?","a":"<p>Pour différencier un syndrome pyramidal d'un syndrome neurogène périphérique :</p><ul><li>Le <strong>syndrome pyramidal</strong> présente : un déficit moteur prédominant sur les muscles <strong>extenseurs aux membres supérieurs et fléchisseurs aux membres inférieurs</strong>, des <strong>ROT vifs et diffus</strong> (sauf si brutal), une <strong>spasticité</strong> et un signe de <strong>Babinski</strong>. Il n'y a pas ou peu d'amyotrophie ni de fasciculations.</li><li>Le <strong>syndrome neurogène périphérique</strong> se caractérise par : un déficit moteur <strong>tronculaire, radiculaire ou distal bilatéral et symétrique</strong>, une <strong>amyotrophie</strong> précoce, des <strong>ROT faibles ou abolis</strong>, une <strong>hypotonie</strong> ou un tonus normal, et des <strong>fasciculations possibles</strong>.</li></ul>"},{"i":"20efbc488caa","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Quels sont les principaux sites où les escarres peuvent apparaître chez un patient alité présentant un déficit moteur des membres inférieurs ?","a":"<p>Les sites les plus fréquents sont les <strong>talons</strong> et le <strong>sacrum</strong>.</p>"},{"i":"690cd1e7a9da","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Quelle est la prise en charge principale de la spasticité en cas de déficit moteur ?","a":"<p>La prise en charge de la spasticité repose sur la <strong>kinésithérapie</strong> associée, si nécessaire, à des injections de <strong>toxine botulique</strong>.</p>"},{"i":"9924ed8bffa6","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Comment prévenir les complications thrombo-emboliques chez un patient alité avec un déficit moteur des membres inférieurs ?","a":"<p>La prévention repose sur :</p><ul><li>une <strong>anticoagulation</strong> à dose isocoagulante si risque élevé,</li><li>la <strong>mobilisation</strong> précoce,</li><li>la <strong>stimulation mécanique</strong> du retour veineux.</li></ul>"},{"i":"a370da301b27","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Comment prévenir et traiter l'algoneurodystrophie du membre supérieur survenant comme complication d'un déficit moteur ou sensitif ?","a":"<p>La prévention se fait par une <strong>kinésithérapie douce et indolore</strong>. Le traitement associe <strong>repos</strong> et <strong>refroidissement</strong> du membre atteint.</p>"},{"i":"a50ccc67090d","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Quelles sont les complications musculo-squelettiques de l'enraidissement en cas de déficit moteur prolongé, notamment en présence d'une hypertonie pyramidale ?","a":"<p>Les complications musculo-squelettiques incluent :</p><ul><li>le risque de <strong>rétraction</strong> (notamment sur hypertonie pyramidale),</li><li>la <strong>périarthrite scapulo-humérale</strong>,</li><li>l'<strong>ostéome para-articulaire</strong> (au niveau du coude ou du genou),</li><li>la <strong>spasticité</strong>.</li></ul>"},{"i":"c521d6dd40bf","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Quels sont les principaux types de complications thrombotiques à craindre chez un patient présentant un déficit moteur d'un ou des deux membres inférieurs et alité ?","a":"<p>Les principales complications à craindre sont les <strong>complications thrombo-emboliques</strong>, notamment la thrombose veineuse profonde et l'embolie pulmonaire.</p>"},{"i":"eea281820490","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Quel est le risque principal des atteintes sensitives, notamment dans le cadre d'un déficit sensitif des membres ?","a":"<p>Le risque principal est l'absence de perception des traumatismes, source de lésions cutanées graves, comme les <strong>brûlures non perçues</strong> à la main ou le <strong>mal perforant plantaire</strong>.</p>"},{"i":"ffa8de494844","n":92,"o":"92-2","u":"Diagnostic positif","t":"Connaître les complications d’un déficit moteur d’un ou deux membres inférieurs","q":"Quelles sont les complications locomotrices traumatiques spécifiques à craindre lors de la reprise de la marche chez un patient ayant présenté un déficit moteur des membres inférieurs ?","a":"<p>Le risque principal est celui de <strong>chutes</strong>, favorisées par le déficit moteur résiduel ou un trouble proprioceptif sévère.</p>"},{"i":"17bf3e358cc9","n":92,"o":"92-3","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires devant un déficit moteur et/ou sensitif d’un membre","q":"Quel examen d'imagerie est essentiel en cas de paraplégie ou tétraplégie d'origine centrale ?","a":"<p>Une <strong>IRM médullaire</strong> est essentielle pour explorer une <strong>paraplégie ou tétraplégie</strong> d'origine centrale.</p>"},{"i":"573a9d475157","n":92,"o":"92-3","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires devant un déficit moteur et/ou sensitif d’un membre","q":"Dans quel délai et avec quel examen d'imagerie doit-on explorer une hémiplégie brutale en urgence ?","a":"<p>Toute <strong>hémiplégie brutale</strong> impose une <strong>IRM cérébrale dans les 4h30</strong> pour le diagnostic différentiel ischémique/hémorragique et la fenêtre de thrombolyse. À défaut, un <strong>scanner cérébral sans injection</strong> doit être réalisé pour éliminer une hémorragie.</p>"},{"i":"9fbb7185220d","n":92,"o":"92-3","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires devant un déficit moteur et/ou sensitif d’un membre","q":"Quels sont les examens biologiques systématiques à réaliser en urgence devant une hémiplégie brutale ?","a":"<p>Les examens biologiques systématiques en urgence devant une hémiplégie brutale incluent : un <strong>NFS</strong>, des <strong>plaquettes</strong>, une <strong>CRP</strong>, un <strong>TP</strong>, un <strong>TCA</strong>, un <strong>ionogramme sanguin</strong>, l'<strong>urée</strong>, la <strong>créatinine</strong>, la <strong>glycémie</strong> et les <strong>enzymes cardiaques</strong>.</p>"},{"i":"b98ef74d2993","n":92,"o":"92-3","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires devant un déficit moteur et/ou sensitif d’un membre","q":"Quels examens complémentaires sont indiqués devant une suspicion de pathologie du système nerveux périphérique, de la jonction neuromusculaire ou des muscles ?","a":"<p>Pour explorer le <strong>système nerveux périphérique</strong> (SNP), la <strong>jonction neuromusculaire</strong> (JNM) ou les <strong>muscles</strong>, l'<strong>ENMG</strong> (Électroneuromyographie) est l'examen clé. Des explorations complémentaires peuvent inclure : <ul><li>La <strong>ponction lombaire</strong> (PL) si une atteinte proximale (polyradiculonévrite aiguë) ou une suspicion de pathologie inflammatoire/infectieuse (SEP, paranéoplasique) est présente.</li><li>Une <strong>biologie sanguine</strong> ciblée (glycémie, électrophorèse des protéines, vitamines B12/B9, TSH) selon l'orientation clinique.</li><li>Une <strong>biopsie musculaire ou neuromusculaire</strong> en cas de suspicion histologique.</li></ul></p>"},{"i":"c496ab033b39","n":92,"o":"92-3","u":"Examens complémentaires","t":"Hiérarchiser les examens complémentaires devant un déficit moteur et/ou sensitif d’un membre","q":"Quels examens complémentaires privilégier en cas de déficit moteur aigu d'origine centrale, spécifiquement devant une hémiplégie ou un syndrome alterne ?","a":"<p>Devant une <strong>hémiplégie</strong>, il faut privilégier une <strong>IRM cérébrale</strong>. En cas de <strong>syndrome alterne</strong>, l'exploration se fera par une <strong>IRM centrée sur le tronc cérébral</strong>.</p>"},{"i":"0536b10bffc4","n":92,"o":"92-5","u":"Diagnostic positif","t":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","q":"Quels signes associés orientent vers une atteinte corticale en présence d'un déficit moteur ou sensitif des membres ?","a":"<p>Une atteinte corticale est suggérée par :</p><ul><li>Une <strong>hémiplégie non proportionnelle</strong>.</li><li>Une <strong>aphasie</strong>.</li><li>Une <strong>héminégligence</strong>.</li><li>Une <strong>hémianopsie</strong>.</li><li>Des <strong>troubles sensitifs corticaux</strong> (par exemple, astéréognosie, extinction).</p></li></ul>"},{"i":"21307e581b5c","n":92,"o":"92-5","u":"Diagnostic positif","t":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","q":"Décrivez le tableau clinique classique du syndrome de Brown-Séquard en cas de lésion de la moelle cervicale haute.","a":"<p>Le syndrome de Brown-Séquard, dû à une hémisection médullaire cervicale haute, se caractérise par :</p><ul><li>Une <strong>hémiparésie</strong> homolatérale à la lésion.</li><li>Une <strong>abolition du tact épicritique et de la proprioception</strong> homolatéraux.</li><li>Une <strong>anesthésie thermoalgique</strong> controlatérale.</p></li></ul>"},{"i":"89b2edf4dc87","n":92,"o":"92-5","u":"Diagnostic positif","t":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","q":"Quels sont les signes caractéristiques d'un syndrome alterne du tronc cérébral ?","a":"<p>Un syndrome alterne du tronc cérébral associe :</p><ul><li>Une atteinte d'un <strong>nerf crânien homolatéral</strong> au site lésionnel.</li><li>Un déficit moteur et/ou sensitif <strong>controlatéral</strong> aux autres signes.</p></li></ul>"},{"i":"8cd519683ec6","n":92,"o":"92-5","u":"Diagnostic positif","t":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","q":"Quels sont les signes associés à une atteinte de la jonction neuromusculaire (JNM) qui orientent le diagnostic ?","a":"<p>Une atteinte de la jonction neuromusculaire se manifeste par :</p><ul><li>Une <strong>fatigabilité</strong> à l'effort.</li><li>Une <strong>fluctuation des symptômes</strong> dans la journée.</li><li>Une atteinte <strong>oculomotrice</strong> (par exemple, <strong>ptosis</strong>, <strong>diplopie</strong>).</li><li>Une atteinte <strong>pharyngo-laryngée</strong> (dysphagie, dysphonie).</p></li></ul>"},{"i":"9b87be2935e6","n":92,"o":"92-5","u":"Diagnostic positif","t":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","q":"Comment différencier une atteinte capsulaire interne d'une atteinte corticale en cas de déficit moteur ?","a":"<p>Une atteinte de la capsule interne se manifeste par une <strong>hémiplégie proportionnelle</strong>, sans signes corticaux associés (contrairement à l'atteinte corticale).</p>"},{"i":"e25ad3694656","n":92,"o":"92-5","u":"Diagnostic positif","t":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","q":"Quelle est la particularité clinique d'un déficit sensitif d'origine thalamique ?","a":"<p>Une atteinte thalamique se traduit par une <strong>hypoesthésie controlatérale proportionnelle</strong> des trois étages (membres supérieur et inférieur, face) et à <strong>tous les modes</strong> (tact, proprioception, thermoalgique), sans déficit moteur associé. C'est un <strong>déficit sensitif pur</strong>.</p>"},{"i":"f70bb3f780ec","n":92,"o":"92-5","u":"Diagnostic positif","t":"Connaître la valeur localisatrice des signes associés au déficit moteur ou périphérique","q":"Quels sont les signes cliniques distinctifs d'un déficit moteur d'origine musculaire ?","a":"<p>Un déficit musculaire se caractérise par :</p><ul><li>Un déficit moteur <strong>proximal et symétrique</strong>.</li><li>Une <strong>abolition du réflexe idiomusculaire</strong>.</li><li>Une <strong>absence de troube sensitif</strong> associé.</p></li></ul>"},{"i":"123067333c6c","n":92,"o":"92-6","u":"Diagnostic positif","t":"Connaître les principaux syndromes médullaires responsables de déficit moteur et sensitif","q":"Quelles sont les atteintes cliniques homolatérales au côté de la lésion dans un syndrome de Brown-Séquard ?","a":"<p>Dans le cadre d'un syndrome de Brown-Séquard, les atteintes cliniques <strong>homolatérales</strong> au côté de la lésion comprennent :</p><ul><li>Une <strong>hémiplégie</strong> (par atteinte du faisceau pyramidal).</li><li>Une <strong>abolition du tact épicritique</strong> (par atteinte de la voie lemniscale).</li><li>Une <strong>abolition de la proprioception</strong> (par atteinte de la voie lemniscale).</li></ul>"},{"i":"1e0c249d46e8","n":92,"o":"92-6","u":"Diagnostic positif","t":"Connaître les principaux syndromes médullaires responsables de déficit moteur et sensitif","q":"Quelle est l'attitude à adopter en urgence face à une compression médullaire comportant un déficit moteur, un niveau sensitif et des troubles sphinctériens ?","a":"<p>Face à une compression médullaire avec déficit moteur, niveau sensitif et troubles sphinctériens, il faut réaliser une <strong>IRM médullaire en urgence</strong> (dans les <strong>6 heures</strong>) et solliciter un <strong>avis neurochirurgical</strong> en urgence.</p>"},{"i":"32dd7bfb3a64","n":92,"o":"92-6","u":"Diagnostic positif","t":"Connaître les principaux syndromes médullaires responsables de déficit moteur et sensitif","q":"Comment se caractérise une atteinte centro-médullaire (comme dans la syringomyélie) sur le plan sensitif ?","a":"<p>Une atteinte centro-médullaire se caractérise par une <strong>hypoesthésie thermoalgique suspendue</strong>, typiquement en « <strong>pèlerine</strong> » cervicale. Elle <strong>préserve les sensibilités lemniscales</strong> (proprioception et tact épicritique).</p>"},{"i":"64ae4530c966","n":92,"o":"92-6","u":"Diagnostic positif","t":"Connaître les principaux syndromes médullaires responsables de déficit moteur et sensitif","q":"Comment se caractérise cliniquement un syndrome de section médullaire complète au niveau moteur et sensitif ?","a":"<p>Un syndrome de section médullaire complète se manifeste par :</p><ul><li>Sur le plan moteur : une <strong>tétra- ou paraplégie flasque</strong> initialement, puis <strong>spastique</strong>, sous-lésionnelle.</li><li>Sur le plan sensitif : une <strong>anesthésie complète à tous les modes</strong> sous-lésionnelle.</li><li>Sur le plan sphinctérien : une <strong>rétention urinaire</strong>, une <strong>rétention fécale</strong> et des <strong>troubles sexuels</strong>.</li></ul>"},{"i":"b37b703daec9","n":92,"o":"92-6","u":"Diagnostic positif","t":"Connaître les principaux syndromes médullaires responsables de déficit moteur et sensitif","q":"Quelles sont les atteintes cliniques controlatérales au côté de la lésion dans un syndrome de Brown-Séquard ?","a":"<p>Dans le cadre d'un syndrome de Brown-Séquard, l'atteinte clinique <strong>controlatérale</strong> au côté de la lésion est une <strong>anesthésie thermoalgique sous-lésionnelle</strong>, due à l'atteinte de la voie spinothalamique qui croise dès la moelle.</p>"}]};